macro.command:
if (args[0].macroPass === "isHit" && workflow.isCritical) {
    await foundry.applications.api.DialogV2.wait({
        window: { title: 'Sacrificial Shield' },
        content: `
            <div class="gps-dialog-container">
                <div class="gps-dialog-section">
                    <div class="gps-dialog-content">
                        <div>
                            <div class="gps-dialog-flex">
                                <p class="gps-dialog-paragraph">Would you like to destroy your shield to prevent a critical hit?</p>
                                <div id="image-container" class="gps-dialog-image-container">
                                    <img src="${macroItem.img}" class="gps-dialog-image">
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        `,
        buttons: [{
            action: "Yes",
            label: "Yes",
            callback: async (event, button, dialog) => {
                workflow.isCritical = false;
                workflow.hitDisplayData[workflow.hitTargets.first().document.uuid].hitString = "hits";

                let actorPlayer = MidiQOL.playerForActor(actor);
                ChatMessage.create({
                    user: actorPlayer.id,
                    content: `The ${macroItem.name} cracks from the heavy impact, but protects its wearer from a critical hit`,
                    speaker: ChatMessage.getSpeaker({ token: token })
                });

                await macroItem.update({
                    "system.equipped": false,
                    "name": `${macroItem.name} (Broken)`
                });
            }
        },
        {
            action: "No",
            label: "No",
            callback: async (event, button, dialog) => {
                return;
            }
        }],
        close: async (event, dialog) => {
            return;
        }, rejectClose:false
    });
}
